contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public entry with parameters: caller (attemptOwner) cannot be changed; we simulate calls
    // by using this contract as msg.sender when invoking c. We supply an owner address and recipient.
    function run(address ownerAddr, address payable recipient, uint amount, bool callAsOwner) public payable {
        require(ownerAddr != address(0) && recipient != address(0));
        // Deploy-time: c already exists and has owner set in its constructor by test harness.
        // Ensure this contract has enough balance to fund c if we send Ether to it.
        require(address(this).balance >= amount);

        // Fund contract c by sending Ether to it from this test contract
        // This is a top-level state-changing call on c: use raw transfer via address(c).call
        // But per constraints we should interact only through c's public surface; c has fallback payable, so call payable fallback
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        // Record balances and owner before the withdrawAll attempt
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        address beforeOwner = c.owner();

        bool reverted;
        // Make the deciding call: we need to call withdrawAll as either owner or non-owner.
        // Since msg.sender will be this contract, to simulate owner vs non-owner we rely on the actual owner stored in c.
        // If callAsOwner is true, require that this contract is the owner so call should succeed; otherwise require it's not owner so call should revert.
        if (callAsOwner) {
            // We cannot change c.owner here; the harness should deploy c with owner = address(this) when callAsOwner is true.
            require(beforeOwner == address(this));
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Ensure this contract is not the owner so the call must revert
            require(beforeOwner != address(this));
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterRecipientBalance = recipient.balance;

        // General rule combining both cases:
        // If call did not revert then c's balance must have become zero and recipient must have received exactly beforeC.
        // If call reverted then c's balance must be unchanged.
        assert(
            (!reverted && afterC == 0 && afterRecipientBalance >= beforeC) ||
            (reverted && afterC == beforeC)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
