    // single public entry: fundAmount used to fund c via this contract, recipient is target of withdrawAll
    function run(address payable recipient, uint fundAmount, bool callerIsOwner) public payable {
        require(recipient != address(0));
        // ensure this test contract has enough balance to fund c
        require(address(this).balance >= fundAmount);

        // Fund contract c by sending Ether to its payable fallback
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok);

        // read observable state before
        uint beforeC = address(c).balance;
        address ownerAddr = c.owner();

        bool reverted;
        // Make the deciding call: we must call c.withdrawAll as this contract (msg.sender == address(this)).
        // To satisfy the shape requirements, each state-changing call on c is a top-level statement.
        if (callerIsOwner) {
            // require that this contract is indeed the owner for the success branch to be meaningful
            require(ownerAddr == address(this));
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // require that this contract is not the owner for the revert branch to be meaningful
            require(ownerAddr != address(this));
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observables after
        uint afterC = address(c).balance;
        uint afterRecipient = recipient.balance;

        // General rule: if call succeeded then c's balance becomes zero and recipient's balance increased by at least beforeC;
        // if call reverted then c's balance unchanged.
        assert((!reverted && afterC == 0 && afterRecipient >= beforeC) || (reverted && afterC == beforeC));
    }

    receive() external payable {}
}

