contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function with parameters: caller (address) is implicit (this contract),
    // so we take owner address to compare and recipient and optionally send Ether to c before withdraw
    function run(address ownerAddr, address payable recipient, uint256 fundAmount, uint256 withdrawAmount) public payable {
        require(recipient != address(0));
        // fund the contract c by sending Ether from this test contract
        // ensure this contract has enough balance to fund
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount, "insufficient balance to fund c");
            (bool sent,) = address(c).call{value: fundAmount}("");
            // funding via fallback; if sending fails we revert test setup
            require(sent, "fund failed");
        }

        // read observable before-values
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        address contractOwner = c.owner();

        bool didRevert;
        // attempt withdrawAll from this contract (msg.sender == address(this))
        try c.withdrawAll(recipient) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        /* General rule asserted:
           - If this contract was the owner of c (i.e., contractOwner == address(this)), then the call must not revert,
             c's balance becomes 0, and the recipient's balance increases by beforeC.
           - Otherwise the call must revert and balances must be unchanged.
        */
        assert(
            (contractOwner == address(this) && !didRevert && afterC == 0 && afterThis == beforeThis + beforeC)
            || (contractOwner != address(this) && didRevert && afterC == beforeC && afterThis == beforeThis)
        );
    }

    // allow receiving Ether when c.transfers to this contract
    receive() external payable {}
}

