        // - If the stored owner is not this test contract, withdrawAll MUST revert and balances remain unchanged.
        assert(
            (contractOwner == address(this) && !didRevert && afterC == 0)
            || (contractOwner != address(this) && didRevert && afterC == beforeC && afterThis == beforeThis)
        );
    }

