contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests with parameters: callerOwner indicates whether this test should act as owner when calling withdrawAll;
    // ownerAddr is the address to set as owner at construction of c (the checker deploys a fresh c with some owner);
    // recipient is the target to receive withdrawn Ether; amount is Ether to send to c before withdrawal.
    function run(address recipient, address callerOwner, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Ensure c has some balance to withdraw by sending Ether to fallback
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        // Read owner and c balance before the withdraw attempt
        address storedOwner = c.owner();
        uint256 beforeBalance = address(c).balance;
        uint256 thisBefore = address(this).balance;

        // Decide who will call withdrawAll: if callerOwner equals storedOwner then the call originates from this contract
        // Otherwise simulate a non-owner by performing the call from this contract but passing a different msg.sender isn't possible.
        // Instead, the property will reason based on equality: if storedOwner == address(this) then this contract is owner and withdraw should succeed;
        // otherwise withdraw should revert. We perform the call from this contract in all cases.

        bool reverted;
        try c.withdrawAll{value:0}(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 thisAfter = address(this).balance;

        // General rule:
        // If this contract is the recorded owner, the call must NOT revert and c's balance becomes zero and recipient receives funds (so c balance decreases by beforeBalance).
        // If this contract is NOT the recorded owner, the call MUST revert and c's balance is unchanged.
        assert(
            (storedOwner == address(this) && !reverted && afterBalance == 0 && (beforeBalance == 0 || afterBalance + beforeBalance == beforeBalance))
            ||
            (storedOwner != address(this) && reverted && afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

