    // Parameters:
    // - callerIsOwner: if true, call withdrawAll from this contract when it is the owner (constructor set);
    // - recipient: address to receive withdrawn funds;
    // - seedFund: amount of wei to fund contract c before withdraw attempt (sent from this contract)
    function run(bool callerIsOwner, address payable recipient, uint256 seedFund) public payable {
        require(address(this).balance >= seedFund, "insufficient balance to seed");

        // Read initial observable state
        address initialOwner = c.owner();
        uint256 beforeBal = address(c).balance;

        // If seedFund > 0, send Ether to C by using its fallback via payable call
        if (seedFund > 0) {
            // send Ether to c
            (bool ok, ) = address(c).call{value: seedFund}("");
            require(ok, "seed transfer failed");
        }

        // After seeding, record balance
        uint256 afterSeedBal = address(c).balance;

        // Decide who should call withdrawAll: if callerIsOwner is true, require that this contract is the owner;
        // otherwise we simulate a non-owner caller by ensuring owner != address(this). If constructor of C set owner
        // differently, the check below will enforce the intended caller role.
        if (callerIsOwner) {
            // ensure this contract is the owner; if not, cannot test owner-case so skip by reverting precondition
            require(initialOwner == address(this), "precondition: this contract must be owner for owner-path");
        } else {
            // ensure this contract is NOT the owner for non-owner path
            require(initialOwner != address(this), "precondition: this contract must NOT be owner for non-owner-path");
        }

        // Attempt withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final balance of c and whether recipient received funds (we can observe only address balances)
        uint256 finalBal = address(c).balance;
        uint256 recipientBal = recipient.balance;

        // General rule asserted:
        // - If caller is owner, the call must NOT revert and final balance equals 0 and contract balance decreased by afterSeedBal.
        // - If caller is NOT owner, the call MUST revert and contract balance must remain equal to afterSeedBal.
        assert(
            (callerIsOwner && !reverted && finalBal == 0 && afterSeedBal >= 0) ||
            (!callerIsOwner && reverted && finalBal == afterSeedBal)
        );
    }

    // Allow test contract to receive ETH when deployed/funded
    receive() external payable {}
}

