    constructor(C _c) { c = _c; }

    function run(address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // record owner observable
        address owner = c.owner();
        bool amOwner = (owner == address(this));

        // record balances before funding
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // fund C by sending ETH to its address (triggers fallback)
        (bool okFund, ) = address(c).call{value: fundAmount}("");
        // okFund may be true even if fundAmount == 0; proceed regardless

        // balances after funding
        uint256 afterFundC = address(c).balance;
        uint256 afterFundRecipient = recipient.balance;

        // attempt withdrawAll as top-level call, capture revert
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // balances after withdraw attempt
        uint256 afterWithdrawC = address(c).balance;
        uint256 afterWithdrawRecipient = recipient.balance;

        // If this contract is owner, withdrawAll must succeed, drain C to zero and increase recipient by the full pre-withdraw C balance (which is afterFundC).
        // If not owner, withdrawAll must revert and balances must remain as after funding.
        assert(
            (amOwner && !reverted && afterWithdrawC == 0 && afterWithdrawRecipient == afterFundRecipient + afterFundC)
            || (!amOwner && reverted && afterWithdrawC == afterFundC && afterWithdrawRecipient == afterFundRecipient)
        );
    }

    receive() external payable {}
}

