contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try withdrawAll by a caller address and ensure only owner can move Ether
    function run(address caller, address payable recipient, uint256 deposit) public payable {
        require(address(this).balance >= deposit);

        // deposit some Ether into c by sending to its fallback
        // note: the InvMutTest contract is the sender when interacting with c
        address(c).call{value: deposit}("");

        // read before-balance and owner
        uint256 before = address(c).balance;
        address owner = c.owner();

        bool reverted;
        // attempt withdrawAll: since msg.sender will be this contract, we simulate calling from this contract
        // To simulate a non-owner attempt, compare caller param to owner: if equal we must perform as owner
        // But we cannot change msg.sender of this contract, so we branch on parameter to decide expected behavior.
        // We perform the actual call; owner check in C uses msg.sender == owner, where msg.sender == address(this).
        // So if caller == address(this) (i.e., user indicates this contract is owner), then the call should succeed.

        // If caller != address(this) we want to assert that non-owner cannot withdraw. To model that, we only perform the call
        // when caller equals address(this) (owner case). For the non-owner case we attempt call and expect revert.

        if (caller == address(this)) {
            // For the owner case, we need c.owner() to equal address(this). But owner is set at deployment of c; we cannot change it here.
            // So require that the provided caller equals the recorded owner to test successful withdraw path.
            require(owner == address(this));

            // perform withdraw as owner
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After successful withdraw (not reverted) the contract's balance must be zero and recipient gained funds.
            // We assert that if call did not revert then c.balance == 0 and if it reverted then balance unchanged.
            assert((!reverted && address(c).balance == 0) || (reverted && address(c).balance == before));
        } else {
            // Non-owner path: perform call and expect it to revert and leave balance unchanged.
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // General rule: when caller parameter is not address(this) (i.e., we are not the owner), the call must revert
            // and the contract balance must remain the same.
            assert(reverted && address(c).balance == before);
        }
    }

    receive() external payable {}
}

