contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking parameters: callerIsOwner determines whether this contract
    // will act as owner when calling withdrawAll; recipient is target address for withdrawal;
    // seedFunds is amount this test will first send into c to set its balance.
    function run(bool callerIsOwner, address payable recipient, uint256 seedFunds) public payable {
        require(address(this).balance >= seedFunds);

        // At deployment time of c the owner was set by its constructor. The checker deploys a fresh c
        // and passes it into this test's constructor. We can observe owner via c.owner().
        address declaredOwner = c.owner();

        // Fund contract c with seedFunds Ether from this test contract to set up balance.
        if (seedFunds > 0) {
            // send Ether to c using the fallback payable
            address(c).call{value: seedFunds}("");
        }

        uint256 beforeBalance = address(c).balance;

        // Decide who should be considered the caller for withdrawAll: this test contract will always be the msg.sender.
        // To emulate calling as owner vs non-owner, we require that declaredOwner equals address(this) when callerIsOwner==true.
        // If that is not the case, then we cannot make this contract be the owner, so make the call expecting revert.
        bool expectsRevert = true;
        if (callerIsOwner && declaredOwner == address(this)) {
            expectsRevert = false;
        }

        bool didRevert;
        // perform the deciding call
        try c.withdrawAll(recipient) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: if call succeeded (didRevert==false) then it must have been allowed (we expected no revert)
        // and all Ether previously in c must now be transferred out (balance == 0). If call reverted, then balance unchanged.
        assert((didRevert == expectsRevert) && (didRevert ? afterBalance == beforeBalance : afterBalance == 0));
    }

    receive() external payable {}
}

