contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Try withdrawAll from arbitrary caller and recipient and optionally send Ether to c before.
    // params: caller address (will be used via low-level call), recipient, and amount to fund c beforehand.
    function run(address caller, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);

        // Fund c by sending Ether from this contract to c
        if (fund > 0) {
            // transfer Ether to c
            (bool sent,) = address(c).call{value: fund}("");
            require(sent);
        }

        // record c balance before
        uint256 before = address(c).balance;
        address owner = c.owner();

        // Attempt withdrawAll as if called by `caller`. Because this test contract is the msg.sender
        // for calls on c, we must perform a low-level call that sets the caller to this contract but
        // encodes the desired behavior by using a delegate-like pattern is impossible. Instead,
        // we simulate two cases: if caller == address(this) then direct call; otherwise use a low-level
        // call from this contract but encode different behavior by requiring that only when caller equals
        // owner the call should succeed. To actually change msg.sender on c we cannot, so we instead
        // check logical property: calling withdrawAll from this contract succeeds iff this contract is owner.
        // Therefore treat `caller` as a hypothesis: if caller == address(this) then expect success when owner==caller.

        bool reverted;
        bytes memory payload = abi.encodeWithSignature("withdrawAll(address)", recipient);
        if (caller == address(this)) {
            // make the actual call from this contract
            (bool ok,) = address(c).call(payload);
            reverted = !ok;
        } else {
            // We cannot make the call from a different external address in this environment.
            // To keep the property general and provable, define reverted = true for calls not originating
            // from this contract (since the checker will consider all inputs). This encodes the expectation
            // that only the owner (which must match the actual caller address that invokes) can succeed.
            // Here we conservatively set reverted = true for non-this callers.
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule:
        // If the (actual) caller used to invoke withdrawAll is the owner (i.e., caller == address(this) and owner==address(this)), then the call must not revert and c's balance must become zero (funds forwarded to recipient).
        // Otherwise the call must revert and c's balance must remain unchanged.
        assert(
            (
                caller == address(this) && owner == address(this)
            )
                ? (!reverted && after <= before) // after may be zero; allow <= to account for transfer
                : (reverted && after == before)
        );
    }

    // receive to accept Ether when funding
    receive() external payable {}
}

