            (bool sent,) = address(c).call{value: fundAmount}("");
            // ensure funding succeeded for the scenario we are going to assert about
            require(sent);
        }

        // record balance before
        uint before = address(c).balance;

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule: if caller (this contract) is the owner, withdraw should succeed and drain all funds to recipient (so c.balance becomes 0);
        // if caller is not the owner, the call must revert and c.balance must remain unchanged.
        bool callerIsOwner = (actualOwner == address(this));

        assert(
            (callerIsOwner && !reverted && after == 0) || (!callerIsOwner && reverted && after == before)
        );
    }

    receive() external payable {}
}
